description:
Context: We have a CDN url https://cdn.hiverhq.com/chat-support/hiver-chat.html  which we want the Lambda to intercept and to perform a 301 redirect to point to https://cdn.hiverhq.com/chat-support/hiver-chat-support.html . 

We can setup a CloudFront behaviour/function to achieve the same if feasible, need devops help on this.
If a lambda already exists which does something similar for our prod CDN in general, that will also suffice.
If not, we can create a new lambda to support such use-cases in our CDN.

I will need some assistance from devops to perform the cost analysis for this function.

Lambda function name: cdn-redirections 
Runtime: Python 3.14

CloudFront function code:
function handler(event) {
    var request = event.request;

    if (request.uri === "/chat-support/hiver-chat.html") {
        return {
            statusCode: 301,
            statusDescription: "Moved Permanently",
            headers: {
                "location": { "value": "/hiver-chat-support.html" }
            }
        };
    }

    return request; 
}

comments.text:
Updated the script to support preservation of query parameters
function handler(event) {
    var request = event.request;

    if (request.uri === "/chat-support/hiver-chat.html") {

        // Build query string from request.querystring
        var qs = "";
        var querystring = request.querystring;

        if (querystring && Object.keys(querystring).length > 0) {
            var params = [];
            for (var key in querystring) {
                if (querystring[key].value !== undefined) {
                    params.push(
                        encodeURIComponent(key) + "=" +
                        encodeURIComponent(querystring[key].value)
                    );
                }
            }
            qs = "?" + params.join("&");
        }

        return {
            statusCode: 301,
            statusDescription: "Moved Permanently",
            headers: {
                "location": {
                    "value": "/chat-support/hiver-chat-support.html" + qs
                }
            }
        };
    }

    return request;
}

